import {PLANS,traffic,formatTime} from './model.mjs';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const num=(n,d=0)=>n==null?'—':Number(n).toLocaleString('en-AU',{maximumFractionDigits:d,minimumFractionDigits:d});
export const money=n=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD',maximumFractionDigits:0}).format(n);
export const pill=(status,text=status)=>`<span class="status-pill ${status==='high'?'danger':status==='watch'?'warn':status==='unknown'?'unknown':''}">${esc(text)}</span>`;
export const btn=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
export const kv=(label,value)=>`<div class="key-value"><span>${label}</span><strong>${value}</strong></div>`;
export const metric=(label,value,detail,r,color='')=>`<div class="metric"><span class="corner">${r}</span><div class="label">${label}</div><div class="value ${color}">${value}</div><div class="detail">${detail}</div></div>`;
export const card=(title,subtitle,body,extra='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${extra}</div>${body}</section>`;
export function metrics(s){return `<div class="metric-grid">${metric('Worker safety',s.worker.status.toUpperCase(),`${num(s.worker.continuous)} min duty · open Worker safety for evidence`,'Worker safety',s.worker.status==='high'?'red':s.worker.status==='watch'?'orange':'')}${metric('Queue length',`${num(s.queue.length)} <small>m</small>`,s.feed?`+${num(s.queue.growth,1)} m/min · virtual warning`:'Unknown · verify site conditions','Queue',s.queue.status==='high'?'red':'')}${metric('Pedestrian detour',s.traffic.pedestrian.reachable?`${num(s.traffic.pedestrian.extraMeters)} <small>m</small>`:'NO ROUTE',`Plan ${s.plan} · ${PLANS[s.plan].name}`,'Planning',s.traffic.pedestrian.reachable?'green':'red')}${metric('Dispatch readiness',s.fleet.feasible?'FEASIBLE':'ACTION',`${s.fleet.changes.length} reassignment${s.fleet.changes.length===1?'':'s'} · 3 vehicles`,'Fleet',s.fleet.feasible?'green':'orange')}</div>`;}
export function road(s){const p=PLANS[s.plan],sx=x=>52+x*.8,sy=y=>247+y,tail=sx(s.traffic.tail),work=sx(p.workStart);return `<div class="map-wrap"><div class="map-tag">SCHEMATIC NETWORK · ${s.feed?'SYNTHETIC TRACKS':'FEED UNAVAILABLE'}</div><svg viewBox="0 0 1060 440" role="img" aria-label="Simulated road network with work zone, queue tail and traffic controller"><defs><pattern id="stripe" width="12" height="12" patternTransform="rotate(45)" patternUnits="userSpaceOnUse"><rect width="6" height="12" fill="#d99b27"/></pattern></defs><rect width="1060" height="440" fill="#e6ede7"/><path d="M0 100H1060M0 359H1060M175 0V440M745 0V440" stroke="#cfdcd3" stroke-width="27"/>${[[55,53,85,70],[220,48,126,60],[395,35,130,76],[570,60,114,48],[810,42,152,70],[61,362,92,48],[240,370,157,48],[510,366,151,61],[799,360,109,57]].map(([x,y,w,h])=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="#d5e0d8" stroke="#c7d4cb"/>`).join('')}<text x="415" y="143" fill="#728477" font-size="13" letter-spacing="3">CREMORNE / DEMO NETWORK</text><rect x="0" y="190" width="1060" height="110" fill="#455761"/><path d="M0 233H1060" stroke="#d0dade" stroke-dasharray="14 13" stroke-width="2"/><path d="M0 194H1060M0 296H1060" stroke="#cbd3d7" stroke-width="2"/><path d="M0 320H690L735 ${s.plan==='B'?320:350}H990" stroke="${s.traffic.pedestrian.reachable?'#459e79':'#c44d4d'}" stroke-width="5" fill="none" stroke-dasharray="${s.traffic.pedestrian.reachable?'0':'8 6'}"/><text x="290" y="340" fill="#37765c" font-size="12">Pedestrian link · ${s.traffic.pedestrian.reachable?`+${p.pedExtra} m`:'disconnected'}</text><path d="M0 171H970" stroke="${s.traffic.bus.reachable?'#789dae':'#c44d4d'}" stroke-width="3" stroke-dasharray="8 6"/><rect x="${work}" y="242" width="${(p.workEnd-p.workStart)*.8}" height="47" fill="#f3ca61" stroke="#cc9a2b"/><rect x="${work}" y="242" width="${(p.workEnd-p.workStart)*.8}" height="8" fill="url(#stripe)"/><text x="${work+8}" y="272" font-size="11" font-weight="700" fill="#614813">WORKS ${s.plan}</text>${s.feed&&s.traffic.length>0?`<rect x="${tail}" y="235" width="${Math.max(0,sx(955)-tail)}" height="25" fill="#dd79483b"/><path d="M${tail} 199V281" stroke="#db7141" stroke-width="2" stroke-dasharray="5 4"/><rect x="${Math.max(12,tail-37)}" y="278" width="91" height="23" rx="4" fill="#fff5e8"/><text x="${Math.max(17,tail-30)}" y="294" font-size="11" font-weight="700" fill="#a75c28">QUEUE TAIL</text>`:''}${s.tracks.map(t=>`<g><rect x="${sx(t.x)-8}" y="${sy(t.y)-6}" width="${t.type==='car'?16:26}" height="12" rx="3" fill="${t.hazard?'#e65a51':t.type==='bus'?'#83b8c7':t.queued?'#e6bea0':'#d9e3e8'}" stroke="#324c59" stroke-width="1"/>${t.hazard?`<rect x="${sx(t.x)-10}" y="${sy(t.y)-10}" width="31" height="20" rx="2" fill="none" stroke="#eb514a" stroke-width="2"/><text x="${sx(t.x)-25}" y="${sy(t.y)+30}" fill="#a63c35" font-weight="700" font-size="11">H-01 · 36 km/h</text>`:''}</g>`).join('')}<ellipse cx="${sx(1000)}" cy="265" rx="28" ry="26" fill="${s.worker.status==='high'?'#dc554740':'#f7cc4640'}" stroke="${s.worker.status==='high'?'#d34843':'#b99a3b'}" stroke-dasharray="5 4"/><circle cx="${sx(1000)}" cy="264" r="7" fill="#f4cf40" stroke="#334750" stroke-width="2"/><path d="M${sx(1000)-5} 273H${sx(1000)+5}" stroke="#334750" stroke-width="3"/><rect x="${sx(1000)-29}" y="307" width="72" height="21" rx="4" fill="white"/><text x="${sx(1000)-22}" y="322" fill="#354e5e" font-size="11" font-weight="700">TC-01</text><g transform="translate(40 62)"><rect width="170" height="58" rx="5" fill="#172931" stroke="#5f777e"/><text x="85" y="24" text-anchor="middle" font-size="12" font-weight="700" fill="#f9ce4e">${s.queue.vms.split('\n')[0]}</text><text x="85" y="43" text-anchor="middle" font-size="12" font-weight="700" fill="#f9ce4e">${s.queue.vms.split('\n')[1]}</text></g><text x="41" y="405" fill="#647c6d" font-size="11">0 m</text><path d="M75 401H185M75 398V404M185 398V404" stroke="#829788"/><text x="194" y="405" fill="#647c6d" font-size="11">illustrative geography · positions in model metres</text>${!s.feed?'<rect width="1060" height="440" fill="#e6ecf2b8"/><rect x="323" y="177" width="415" height="94" rx="10" fill="#122c3eee"/><text x="530" y="212" text-anchor="middle" fill="white" font-size="18" font-weight="700">Sensor stream unavailable</text><text x="530" y="241" text-anchor="middle" fill="#b4c7d4" font-size="13">Live risk is unknown. Planning model remains available.</text>':''}</svg></div><div class="legend"><span><i class="dot" style="background:#f1c746"></i>Controller / work zone</span><span><i class="dot" style="background:#d78a50"></i>Queue estimate</span><span><i class="dot" style="background:#459e79"></i>Pedestrian link</span><span><i class="dot" style="background:#789dae"></i>Bus corridor</span></div>`;}
export function events(s){return s.events.length?s.events.map(e=>`<div class="event-item"><div class="event-top"><span class="tag ${e.severity==='high'?'red':'orange'}">${({R1:'Worker safety',R2:'Queue warnings',R3:'Work-zone planning',R4:'Fleet & charging',SYSTEM:'Model data'})[e.module]||e.module} · ${e.severity.toUpperCase()}</span><span class="muted" style="font-size:11px">${e.acknowledged?'ACKNOWLEDGED':'ACTIVE'}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.detail)}</p><div class="actions">${btn('Inspect','inspect','small',`data-id="${esc(e.id)}"`)}${btn(e.acknowledged?'Received':'Acknowledge','ack','small',`data-id="${esc(e.id)}" ${e.acknowledged?'disabled':''}`)}</div></div>`).join(''):'<div class="empty">No active alerts in this scenario.<br>Open Worker safety to test a vehicle approach.</div>';}
export function signs(s){return `<div class="signs"><div class="vms">${s.queue.vms.replace('\n','<br>')}</div><div><div class="speed-sign">${s.queue.speed??'—'}</div><p class="note" style="text-align:center">virtual km/h</p></div></div>`;}
export function queueChart(s,a){const max=Math.max(210,traffic('A',a,a.horizon).length,traffic('B',a,a.horizon).length),x=t=>50+t/a.horizon*600,y=q=>190-q/max*150;return `<svg class="chart" viewBox="0 0 690 230" role="img" aria-label="Queue growth comparison for plans A and B">${[0,.5,1].map(v=>`<path d="M50 ${y(v*max)}H650" stroke="#e5ecef"/><text x="42" y="${y(v*max)+4}" text-anchor="end" fill="#738693" font-size="11">${num(v*max)}</text>`).join('')}<text x="16" y="15" fill="#738693" font-size="11">metres</text>${['A','B'].map(p=>`<path d="${Array.from({length:31},(_,i)=>`${i?'L':'M'}${x(i*a.horizon/30)},${y(traffic(p,a,i*a.horizon/30).length)}`).join(' ')}" fill="none" stroke="${p==='A'?'#d99c46':'#258c78'}" stroke-width="3"/>`).join('')}<path d="M${x(s.time)} 30V190" stroke="#6e7f8a" stroke-dasharray="5 4"/><text x="50" y="212" font-size="11" fill="#738693">08:00</text><text x="650" y="212" text-anchor="end" font-size="11" fill="#738693">${formatTime(480+a.horizon/60)}</text><text x="464" y="18" fill="#be802c" font-size="12">● Plan A</text><text x="560" y="18" fill="#258c78" font-size="12">● Plan B</text></svg>`;}
export function costChart(cost){const max=Math.max(...cost.years.flatMap(v=>[v.diesel,v.mixed]));return `<svg class="chart" viewBox="0 0 570 245" role="img" aria-label="Cumulative five-year costs for diesel and mixed EV fleet"><text x="28" y="19" fill="#718592" font-size="11">Cumulative AUD · year 5 includes resale value</text>${cost.years.map((v,i)=>{const x=40+i*86,h1=v.diesel/max*150,h2=v.mixed/max*150;return `<rect x="${x}" y="${200-h1}" width="25" height="${h1}" rx="3" fill="#9eb4c5"/><rect x="${x+29}" y="${200-h2}" width="25" height="${h2}" rx="3" fill="#427f7c"/><text x="${x+26}" y="221" text-anchor="middle" fill="#718592" font-size="11">${i===0?'Purchase':`Year ${i}`}</text>`;}).join('')}</svg><div class="legend"><span><i class="dot" style="background:#9eb4c5"></i>3 new diesel</span><span><i class="dot" style="background:#427f7c"></i>2 diesel + 1 EV + charger</span></div>`;}
export function schedule(f){return `<div class="card-body"><div class="note" style="display:flex;justify-content:space-between;margin-left:100px"><span>08:00</span><span>10:00</span><span>13:00</span></div>${f.vehicles.map(v=>`<div class="schedule-row"><span><strong>${v.id}</strong><br>${num(v.km)} km</span><div class="schedule-track">${f.rows.filter(j=>j.vehicle===v.id).map(j=>`<div class="schedule-job" title="${esc(j.label)} · ${formatTime(j.start)}–${formatTime(j.end)}" style="left:${(j.start-480)/300*100}%;width:${(j.end-j.start)/300*100}%;${!j.energyValid||!j.payloadValid?'background:#cf6b59':''}">${j.id}</div>`).join('')}${f.charges.filter(c=>c.vehicle===v.id).map(c=>`<div class="schedule-job charge" title="Charge ${num(c.kwh,1)} battery kWh" style="left:${(c.start-480)/300*100}%;width:${(c.end-c.start)/300*100}%">⚡</div>`).join('')}</div></div>`).join('')}<div class="legend"><span><i class="dot" style="background:#4b899d"></i>Delivery / service</span><span><i class="dot" style="background:#cf6b59"></i>Constraint failure</span><span><i class="dot" style="background:#7753ba"></i>Depot charging</span></div><p class="note">All jobs are depot-to-depot round trips. Fixed windows include travel and handling. Payload compatibility, overlapping jobs and energy reserve are checked.</p></div>`;}
